import base64
import json
import os
from typing import Any, Dict, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _read_document_bytes(source: Any) -> bytes:
    if source is None:
        raise ValueError("A document source is required.")

    if isinstance(source, bytes):
        return source

    if isinstance(source, str):
        if source.startswith("http://") or source.startswith("https://"):
            import requests

            resp = requests.get(source, timeout=60)
            resp.raise_for_status()
            return resp.content
        if os.path.exists(source):
            with open(source, "rb") as f:
                return f.read()
        try:
            return base64.b64decode(source, validate=True)
        except Exception as e:
            raise ValueError("String source must be a valid file path, URL, or base64 content.") from e

    if hasattr(source, "read"):
        data = source.read()
        if isinstance(data, str):
            return data.encode("utf-8")
        return data

    raise TypeError("Unsupported document source type.")


def _normalize_currency_amount(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, dict):
        for k in ("amount", "value", "total"):
            if k in value:
                value = value[k]
                break
    try:
        return float(value)
    except Exception:
        return None


def _to_standard_schema(result: Any) -> Dict[str, Any]:
    documents = getattr(result, "documents", None) or []
    doc = documents[0] if documents else None
    fields = getattr(doc, "fields", {}) if doc else {}

    def field_value(name: str) -> Any:
        f = fields.get(name)
        if not f:
            return None
        for attr in ("value", "content", "value_string", "value_date", "value_time", "value_number"):
            v = getattr(f, attr, None)
            if v not in (None, ""):
                return v
        try:
            return f.to_dict()
        except Exception:
            return None

    merchant_name = field_value("MerchantName")
    transaction_date = field_value("TransactionDate")
    invoice_id = field_value("InvoiceId")
    customer_name = field_value("CustomerName")
    customer_address = field_value("CustomerAddress")
    merchant_address = field_value("MerchantAddress")
    subtotal = _normalize_currency_amount(field_value("SubTotal"))
    total = _normalize_currency_amount(field_value("Total"))
    tax = _normalize_currency_amount(field_value("TotalTax"))
    currency = field_value("CurrencyCode") or field_value("Currency")

    line_items = []
    raw_items = field_value("Items")
    if isinstance(raw_items, list):
        for item in raw_items:
            item_fields = getattr(item, "value", None)
            if item_fields is None and isinstance(item, dict):
                item_fields = item
            item_fields = item_fields or {}
            line_items.append(
                {
                    "description": item_fields.get("Description", {}).get("value", None)
                    if isinstance(item_fields.get("Description"), dict)
                    else getattr(item_fields.get("Description"), "value", None)
                    or getattr(item_fields.get("Description"), "content", None),
                    "quantity": _normalize_currency_amount(
                        item_fields.get("Quantity", {}).get("value", None)
                        if isinstance(item_fields.get("Quantity"), dict)
                        else getattr(item_fields.get("Quantity"), "value", None)
                    ),
                    "unit_price": _normalize_currency_amount(
                        item_fields.get("UnitPrice", {}).get("value", None)
                        if isinstance(item_fields.get("UnitPrice"), dict)
                        else getattr(item_fields.get("UnitPrice"), "value", None)
                    ),
                    "amount": _normalize_currency_amount(
                        item_fields.get("Amount", {}).get("value", None)
                        if isinstance(item_fields.get("Amount"), dict)
                        else getattr(item_fields.get("Amount"), "value", None)
                    ),
                }
            )

    return {
        "provider": "azure_document_intelligence",
        "document_type": "invoice",
        "invoice_id": invoice_id,
        "merchant_name": merchant_name,
        "merchant_address": merchant_address,
        "customer_name": customer_name,
        "customer_address": customer_address,
        "transaction_date": transaction_date,
        "currency": currency,
        "subtotal": subtotal,
        "tax": tax,
        "total": total,
        "line_items": line_items,
        "raw": result.to_dict() if hasattr(result, "to_dict") else {},
    }


def normalize_expense_fields(document_source: Any) -> Dict[str, Any]:
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise EnvironmentError(
            "AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY are required."
        )

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    document_bytes = _read_document_bytes(document_source)

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        body=document_bytes,
        content_type="application/octet-stream",
    )
    result = poller.result()
    return _to_standard_schema(result)
